use xiom.io;

use xiom.string;
fn has_uppercase(pw: Str) -> Bool {
  return string.str_lower(pw) != pw;
}

fn has_digit(pw: Str) -> Bool {
  return string.str_contains(pw, "0") || string.str_contains(pw, "1") || string.str_contains(pw, "2") || string.str_contains(pw, "3") || string.str_contains(pw, "4") || string.str_contains(pw, "5") || string.str_contains(pw, "6") || string.str_contains(pw, "7") || string.str_contains(pw, "8") || string.str_contains(pw, "9");
}

fn validate(pw: Str) -> Result[Str, Str] {
  if string.str_len(pw) < 8 {
    return Err("Too short — need 8+ characters");
  }
  if !has_uppercase(pw) {
    return Err("Missing uppercase letter");
  }
  if !has_digit(pw) {
    return Err("Missing digit");
  }
  return Ok("Password is valid");
}

fn main() -> Int {
  match validate("Hello123") {
    Ok(_) => { return 200; }
    Err(_) => { return 400; }
  }
}
